settings.custom_css:
selector {
  border-radius: 72px;
  border-top: 2px solid #1B5A3A;
  background: linear-gradient(90deg, #0A2417 0%, #081B11 50%, #05140D 100%);
  outline: none;
  cursor: pointer;
  border: none;
  transition: 0.5s;
  position: relative;
  overflow: hidden;
  display: inline-flex;
  align-items: center;
  color: white;
}
selector .elementor-button-icon {
  font-size: 17px;
  color: white;
  margin-right: 8px;
  transition: transform 0.5s ease;
}

selector:hover .elementor-button-icon {
  transform: translateX(5px) rotate(5deg);
}

selector:active {
  opacity: 0.5;
}

selector::before {
  content: '';
  background: linear-gradient(10deg, rgba(236, 255, 246, 0.90) 12.81%, rgba(236, 255, 246, 0.00) 66.66%);
  width: 70px;
  height: 130%;
  position: absolute;
  transform: translateX(-50%) skew(-25deg);
  bottom: 0%;
  user-select: none;
  pointer-events: none;
  animation: shinery 3s infinite ease-in-out;
  filter: blur(3px);
}

@keyframes shinery {
  0%, 100% {
    left: -10%;
    opacity: 0;
  }
  20% {
    opacity: 1;
  }
  48% {
    left: 110%;
    opacity: 1;
  }
  51% {
    opacity: 0;
  }
}

selector:hover {
  transform: translateY(-8px);
  box-shadow: none;
  transition: 0.5s;
}

selector svg {
  font-size: 14px;
}

selector:after {
  content: "";
  position: absolute;
  top: -10px;
  left: 50%;
  transform: translateX(-50%);
  width: 90%;
  height: 20px;
  background: radial-gradient(ellipse at center, rgba(46, 255, 172, 0.25) 20%, rgba(46, 255, 172, 0.10) 70%, rgba(46, 255, 172, 0.00) 100%);
  mix-blend-mode: screen;
  filter: blur(12px);
  pointer-events: none;
  z-index: 1;
}

selector .elementor-button:before {
  content: "";
  position: absolute;
  top: -5px;
  left: 50%;
  transform: translateX(-50%);
  width: 100%;
  height: 10px;
  background: radial-gradient(ellipse at center, rgba(255,255,255,1) 0%, rgba(255,255,255,0.12) 40%, rgba(255,255,255,0) 70%);
  pointer-events: none;
  z-index: 2;
}

selector .elementor-button:after {
  content: "";
  position: absolute;
  bottom: -4.5px;
  left: 50%;
  transform: translateX(-50%);
  width: 100%;
  height: 10px;
  background: radial-gradient(ellipse at center, rgba(255,255,255,1) 0%, rgba(255,255,255,0.12) 40%, rgba(255,255,255,0) 70%);
  pointer-events: none;
  z-index: 2;
}

